alter table public.work_orders add column if not exists production_code text, add column if not exists category text, add column if not exists production_area text, add column if not exists supervisor_employee_id uuid references public.employees(id) on delete set null, add column if not exists designer_employee_id uuid references public.employees(id) on delete set null, add column if not exists assigned_employee_id uuid references public.employees(id) on delete set null, add column if not exists planned_start_at timestamptz, add column if not exists planned_end_at timestamptz, add column if not exists actual_end_at timestamptz, add column if not exists estimated_hours numeric(12,2) not null default 0, add column if not exists actual_hours numeric(12,2) not null default 0, add column if not exists progress_percent numeric(5,2) not null default 0, add column if not exists quality_status text not null default 'PENDING', add column if not exists materials_status text not null default 'PENDING', add column if not exists installation_required boolean not null default false, add column if not exists installation_address text, add column if not exists installation_contact text, add column if not exists installation_phone text, add column if not exists estimated_cost numeric(14,2) not null default 0, add column if not exists actual_cost numeric(14,2) not null default 0, add column if not exists waste_cost numeric(14,2) not null default 0, add column if not exists rework_cost numeric(14,2) not null default 0, add column if not exists blocked_reason text, add column if not exists cancellation_reason text, add column if not exists tags text[] not null default '{}';
create table if not exists public.production_tasks(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,work_order_id uuid not null references public.work_orders(id) on delete cascade,title text not null,process_type text not null default 'PRODUCTION',status text not null default 'PENDING',sequence_no integer not null default 0,assigned_employee_id uuid references public.employees(id) on delete set null,estimated_minutes integer not null default 0,actual_minutes integer not null default 0,machine_name text,instructions text,checklist jsonb not null default '[]'::jsonb,started_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.production_material_requirements(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,work_order_id uuid not null references public.work_orders(id) on delete cascade,inventory_item_id uuid references public.inventory_items(id) on delete set null,material_name text not null,unit text not null default 'unidad',required_qty numeric(14,4) not null default 0,reserved_qty numeric(14,4) not null default 0,consumed_qty numeric(14,4) not null default 0,waste_qty numeric(14,4) not null default 0,unit_cost numeric(14,4) not null default 0,status text not null default 'PENDING',notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.production_status_history(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,work_order_id uuid not null references public.work_orders(id) on delete cascade,from_status text,to_status text not null,comment text,changed_by uuid default auth.uid(),changed_at timestamptz not null default now());
create index if not exists idx_work_orders_company_status_due on public.work_orders(company_id,status,due_at); create index if not exists idx_work_orders_company_priority on public.work_orders(company_id,priority); create index if not exists idx_production_tasks_order_sequence on public.production_tasks(work_order_id,sequence_no); create index if not exists idx_production_tasks_company_status on public.production_tasks(company_id,status); create index if not exists idx_production_materials_order on public.production_material_requirements(work_order_id); create index if not exists idx_production_materials_inventory on public.production_material_requirements(inventory_item_id); create index if not exists idx_production_history_order on public.production_status_history(work_order_id,changed_at desc);
alter table public.production_tasks enable row level security; alter table public.production_material_requirements enable row level security; alter table public.production_status_history enable row level security;
do $$ declare t text; begin foreach t in array array['production_tasks','production_material_requirements','production_status_history'] loop execute format('drop policy if exists %I on public.%I','company_members_access',t); execute format('create policy %I on public.%I for all to authenticated using (exists (select 1 from public.company_members cm where cm.company_id = %I.company_id and cm.user_id = (select auth.uid()))) with check (exists (select 1 from public.company_members cm where cm.company_id = %I.company_id and cm.user_id = (select auth.uid())))','company_members_access',t,t,t); execute format('grant select,insert,update,delete on public.%I to authenticated',t); end loop; end $$;